-- Estrutura de um faturamento da Mascote
SELECT * FROM faturamentos WHERE tenantId = 1 AND empresaSlug = 'MASCOTE' LIMIT 3;

-- Estrutura de uma meta da Mascote
SELECT * FROM metas WHERE tenantId = 1 AND empresaSlug = 'MASCOTE' LIMIT 3;

-- Total de registros a copiar
SELECT COUNT(*) as total_faturamentos FROM faturamentos WHERE tenantId = 1 AND empresaSlug = 'MASCOTE';
SELECT COUNT(*) as total_metas FROM metas WHERE tenantId = 1 AND empresaSlug = 'MASCOTE';

